head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setHeaderHide]<br/>GridView 컴포넌트의 hideHeader 속성을 설정합니다.",
    "validation" : [
        "hide(선택) 파라미터를 true 로 설정 시 Header 영역을 숨김 처리해야 합니다.",
        "hide(선택) 파라미터를 false 로 설정 시 Header 영역을 표시해야 합니다.",
        "hide(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
        "Header 영역을 'display:none' 으로 숨김 처리하므로 메소드를 사용한 Header Column 접근이 가능해야 합니다.",
        "Header 영역의 th 요소 class 속성은 다시 표시될 때 이전값으로 복원되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (기본 Header column1~column4 / Body col1~col4)
    await $c.gcm.createBasicGridView(cList);
}



// 첫번째 Header th 의 현재 class 속성을 반환 (@spec class 복원 검증용)
scwin.getFirstHeaderThClass = function () {
    let th = document.querySelector("[id*='target1_head_table'] th");
    return th ? th.getAttribute("class") : null;
}



scwin.btn_setHeaderHide_onclick = function () {
    let hideText = par_hide.getValue();

    if (hideText === 'omit') {
        // 파라미터 생략 (기본값 false → Header 표시)
        target1.setHeaderHide();
        wf_body_bottom.getObj("scwin").setReturnValue("setHeaderHide()");
    } else {
        let hide = hideText === 'true';
        target1.setHeaderHide(hide);
        wf_body_bottom.getObj("scwin").setReturnValue("setHeaderHide(" + hide + ")");
    }

    // 실행 결과 : Header 영역(head_table)의 display 상태 확인
    let headTable = document.querySelector("[id*='target1_head_table']");
    if (headTable) {
        let displayValue = window.getComputedStyle(headTable).display;
        wf_body_bottom.getObj("scwin").setReturnValue("Header 영역 display : " + displayValue);
        wf_body_bottom.getObj("scwin").setReturnValue("Header 영역 숨김 여부 : " + (displayValue === "none"));
    }

    // @spec 검증 : Header th 요소의 class 속성 확인
    wf_body_bottom.getObj("scwin").setReturnValue("현재 th class : " + scwin.getFirstHeaderThClass());
}
